package com.example.orderprocessing.controller;
import com.example.orderprocessing.dto.OrderRequest; import com.example.orderprocessing.entity.OrderStatus; import com.example.orderprocessing.service.*; import jakarta.validation.Valid; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @RequestMapping("/api/orders") public class OrderController { private final OrderService service; private final EventHub events; public OrderController(OrderService service,EventHub events){this.service=service;this.events=events;} @GetMapping public Object all(@RequestParam(required=false) String search,@RequestParam(required=false) OrderStatus status){return service.search(search,status).stream().map(service::orderView).toList();} @GetMapping("/{id}") public Object get(@PathVariable Long id){return service.orderView(service.get(id));} @PostMapping public Object create(@Valid @RequestBody OrderRequest request){return service.orderView(service.create(request));} @PutMapping("/{id}/status") public Object status(@PathVariable Long id,@RequestParam OrderStatus value){return service.orderView(service.changeStatus(id,value));} @PostMapping("/{id}/cancel") public Object cancel(@PathVariable Long id){return service.orderView(service.changeStatus(id,OrderStatus.CANCELLED));} @PostMapping("/{id}/retry") public Object retry(@PathVariable Long id){return service.orderView(service.retry(id));} @PostMapping("/dead-letter/{id}/retry") public Object retryDeadLetter(@PathVariable Long id){return service.orderView(service.retry(id));} @GetMapping(value="/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter events(){return events.subscribe();} @GetMapping("/dead-letter") public Object dlq(){return service.all().stream().filter(o->o.getStatus().name().equals("DEAD_LETTER")).map(service::orderView).toList();} }
